<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import type { Coords } from '@darts/schema';
import { boardCells, BULL_INNER_R, BULL_OUTER_R, C, mmToSvg, NUMBERS } from '../boardGeometry.ts';
import { isNearScoringBoundary } from '../captureBoundary.ts';

type Status = 'confirmed' | 'incorrect' | 'uncertain' | 'unreviewed';
interface Camera { camera: number; url: string | null; error?: string | null }
interface Review { status: Status; reason?: string | null; correctedCoords?: Coords | null; notes?: string | null }
interface Occupancy { throws?: Array<{ coords?: Coords | null; segment?: { number?: number; ring?: string } }> }
interface Capture { captureId: string; type?: string; reportedThrow: { segment?: { number?: number; ring?: string; name?: string; label?: string }; value?: number; coords?: Coords | null } | null; reportedOccupancyBefore?: Occupancy | null; reportedOccupancyAfter?: Occupancy | null; capturedAt?: string; captureStartedAt?: string; cameras: Camera[]; review?: Review; [key: string]: unknown }
const captures = ref<Capture[]>([]), activeId = ref(''), loading = ref(true), saving = ref(false), error = ref('');
const filter = ref<'all' | Status>('unreviewed'), lightbox = ref<Camera | null>(null), reason = ref(''), notes = ref(''), corrected = ref<Coords | null>(null);
const showBaselines = ref(false);
const nearEdgeOnly = ref(true), edgeDistance = ref(3);
const cells = boardCells();
const active = computed(() => captures.value.find(c => c.captureId === activeId.value) ?? null);
const rawScope = computed(() => captures.value.filter(c => showBaselines.value || c.type === 'throw'));
function hasFinitePosition(p: Coords | null | undefined): boolean { return !!p && Number.isFinite(p.x) && Number.isFinite(p.y); }
const skipped = computed(() => nearEdgeOnly.value ? rawScope.value.filter(c => c.type === 'throw' && hasFinitePosition(c.reportedThrow?.coords) && !isNearScoringBoundary(c.reportedThrow?.coords, edgeDistance.value)).length : 0);
const scope = computed(() => rawScope.value.filter(c => !nearEdgeOnly.value || c.type !== 'throw' || !hasFinitePosition(c.reportedThrow?.coords) || isNearScoringBoundary(c.reportedThrow?.coords, edgeDistance.value)));
const totals = computed(() => ({ all: scope.value.length, reviewed: scope.value.filter(c => c.review?.status && c.review.status !== 'unreviewed').length, confirmed: scope.value.filter(c => c.review?.status === 'confirmed').length, incorrect: scope.value.filter(c => c.review?.status === 'incorrect').length, uncertain: scope.value.filter(c => c.review?.status === 'uncertain').length }));
const visible = computed(() => scope.value.filter(c => filter.value === 'all' || (c.review?.status ?? 'unreviewed') === filter.value));
const index = computed(() => visible.value.findIndex(c => c.captureId === activeId.value));
const coords = computed(() => active.value?.reportedThrow?.coords ?? null);
const coordsUsable = computed(() => !!coords.value && Number.isFinite(coords.value.x) && Number.isFinite(coords.value.y));
const occupancy = computed(() => active.value?.reportedOccupancyAfter?.throws?.length ? active.value.reportedOccupancyAfter.throws : active.value?.reportedOccupancyBefore?.throws ?? []);
const segment = computed(() => { const s = active.value?.reportedThrow?.segment; return s?.label ?? s?.name ?? (s?.ring === 'BULL' ? 'Bull' : s?.ring === 'OUTER_BULL' ? 'Outer bull' : s?.number ? `${s.ring?.replaceAll('_', ' ')} ${s.number}` : 'Unknown segment'); });
const when = computed(() => { const raw = active.value?.captureStartedAt ?? active.value?.capturedAt; const d = raw ? new Date(raw) : null; return d && !Number.isNaN(+d) ? d.toLocaleString() : raw ?? 'Time unavailable'; });
async function load() { loading.value = true; error.value = ''; try { const r = await fetch('/api/captures'); if (!r.ok) throw new Error('Could not load captures (' + r.status + ')'); const data = await r.json(); captures.value = data.captures; if (!captures.value.some(c => c.captureId === activeId.value)) activeId.value = visible.value[0]?.captureId ?? ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
async function open(id: string) { activeId.value = id; error.value = ''; try { const r = await fetch('/api/captures/' + encodeURIComponent(id)); if (!r.ok) throw new Error('Could not load capture (' + r.status + ')'); const data = await r.json(); const i = captures.value.findIndex(c => c.captureId === id); if (i >= 0) captures.value[i] = data.capture; } catch (e) { error.value = (e as Error).message; } }
watch(active, c => { reason.value = c?.review?.reason ?? ''; notes.value = c?.review?.notes ?? ''; corrected.value = c?.review?.correctedCoords ?? null; }, { immediate: true });
function ensureVisible() { if (!visible.value.some(c => c.captureId === activeId.value)) activeId.value = visible.value[0]?.captureId ?? ''; }
function updateEdgeFilter() { edgeDistance.value = Math.max(0.5, Math.min(15, Number(edgeDistance.value) || 0.5)); ensureVisible(); }
function setFilter(value: 'all' | Status) { filter.value = value; ensureVisible(); }
function move(d: number) { if (saving.value) return; const c = visible.value[index.value + d]; if (c) void open(c.captureId); }
async function save(status: Status) { if (!active.value || saving.value) return; const captureId = active.value.captureId; const nextId = visible.value[index.value + 1]?.captureId; saving.value = true; error.value = ''; try { const r = await fetch('/api/captures/' + encodeURIComponent(captureId), { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ status, reason: reason.value || undefined, correctedCoords: corrected.value, notes: notes.value || undefined }) }); if (!r.ok) throw new Error('Could not save review (' + r.status + ')'); const data = await r.json(); const i = captures.value.findIndex(c => c.captureId === captureId); if (i >= 0) captures.value[i] = { ...captures.value[i], review: data.review }; if (status !== 'unreviewed') { if (nextId) await open(nextId); else ensureVisible(); } } catch (e) { error.value = (e as Error).message; } finally { saving.value = false; } }
function key(e: KeyboardEvent) { const el = e.target as HTMLElement | null; if (el && (['INPUT','TEXTAREA','SELECT'].includes(el.tagName) || el.isContentEditable)) return; if (lightbox.value) { if (e.key === 'Escape') lightbox.value = null; return; } if (e.key === 'ArrowLeft') { e.preventDefault(); move(-1); } if (e.key === 'ArrowRight') { e.preventDefault(); move(1); } if (e.key === '1') void save('confirmed'); if (e.key === '2') void save('incorrect'); if (e.key === '3') void save('uncertain'); }
function xy(p: Coords | null | undefined) { return p ? mmToSvg(p) : null; }
const correctedX = computed({ get: () => corrected.value?.x, set: (v: number | undefined) => { corrected.value = v == null || Number.isNaN(v) ? null : { ...(corrected.value ?? { x: 0, y: 0 }), x: v }; } });
const correctedY = computed({ get: () => corrected.value?.y, set: (v: number | undefined) => { corrected.value = v == null || Number.isNaN(v) ? null : { ...(corrected.value ?? { x: 0, y: 0 }), y: v }; } });
onMounted(() => { void load(); window.addEventListener('keydown', key); }); onUnmounted(() => window.removeEventListener('keydown', key));
</script>

<template>
 <main class="capture">
  <header class="hero"><div><div class="brand"><span class="brand-mark">◎</span><span>DARTS <i>/ BOARD DATA</i></span></div><p class="eyebrow">Real board · local captures</p><h1>Capture review</h1><p class="lede">Check each reported hit against the original camera frames. Record your assessment alongside the capture.</p></div><div class="summary"><div class="summary-top"><b>{{ totals.reviewed }} <small>/ {{ totals.all }}</small></b><span>reviewed</span></div><div class="progress"><i :style="{ width: totals.all ? (totals.reviewed / totals.all * 100) + '%' : '0%' }"/></div><div class="counts"><span><i class="dot green"/> {{ totals.confirmed }} confirmed</span><span><i class="dot red"/> {{ totals.incorrect }} incorrect</span><span><i class="dot amber"/> {{ totals.uncertain }} uncertain</span></div></div></header>
  <div class="bar"><div class="filters"><button v-for="f in (['all','unreviewed','confirmed','incorrect','uncertain'] as const)" :key="f" :disabled="saving" :class="{ active: filter === f }" @click="setFilter(f)">{{ f === 'all' ? 'All throws' : f === 'unreviewed' ? 'To review' : f }}</button><label class="baseline-toggle"><input v-model="showBaselines" type="checkbox" @change="ensureVisible"/> Include empty-board baselines</label></div><button class="refresh" @click="load">↻ <span>Refresh</span></button></div>
  <div class="edge-filter"><label><input v-model="nearEdgeOnly" :disabled="saving" type="checkbox" @change="updateEdgeFilter"/> Review only positions within</label><input v-model.number="edgeDistance" :disabled="saving" aria-label="Boundary distance in millimetres" type="number" min="0.5" max="15" step="0.5" @change="updateEdgeFilter"/><span>mm of a scoring boundary</span><b v-if="nearEdgeOnly" class="edge-badge">≤ {{ edgeDistance }} mm</b><span class="skip-count">{{ skipped }} filtered from totals</span></div>
  <p v-if="error" class="error" role="alert">{{ error }}</p>
  <div v-if="loading" class="state"><span class="spinner"/> Loading capture library…</div>
  <div v-else-if="!captures.length" class="state empty"><span class="empty-mark">◎</span><h2>No captures yet</h2><p>New throws saved by the board collector will appear here.</p></div>
  <div v-else-if="!active" class="state empty"><h2>No captures in this view</h2><p>Pick another filter to continue.</p></div>
  <template v-else>
   <div class="navigator"><button :disabled="saving || index <= 0" @click="move(-1)">← <span>Previous</span></button><div class="position">Capture <b>{{ index + 1 }}</b><span> / {{ visible.length }}</span></div><select :disabled="saving" :value="activeId" aria-label="Jump to capture" @change="open(($event.target as HTMLSelectElement).value)"><option v-for="c in visible" :key="c.captureId" :value="c.captureId">{{ c.captureId }}</option></select><button :disabled="saving || index >= visible.length - 1" @click="move(1)"><span>Next</span> →</button></div>
   <div class="columns">
    <section class="panel evidence"><div class="panel-head"><div><span class="kicker">01 / EVIDENCE</span><h2>Camera frames</h2></div><span class="small-note">Original stills · {{ active.cameras.filter(c => c.url).length }} available</span></div>
     <div class="camera-grid"><button v-for="cam in active.cameras" :key="cam.camera" class="camera" :disabled="!cam.url" @click="lightbox = cam"><div class="frame"><img v-if="cam.url" :src="cam.url" :alt="'Original frame from camera ' + cam.camera"/><span v-else class="unavailable">Image unavailable</span><span v-if="cam.url" class="expand">↗</span></div><div class="camera-caption"><b>Camera {{ cam.camera }}</b><span>{{ cam.error ? 'capture issue' : cam.url ? 'original frame' : 'missing frame' }}</span></div></button><div v-if="!active.cameras.length" class="no-frames">No camera frames recorded for this capture.</div></div>
     <div class="metadata"><div><span>BOARD LABEL</span><b class="segment">{{ segment }}</b></div><div><span>CAPTURE TIME</span><b>{{ when }}</b></div><div><span>REPORTED POSITION</span><b v-if="coordsUsable">x {{ coords!.x.toFixed(1) }} <small>mm</small><em>·</em> y {{ coords!.y.toFixed(1) }} <small>mm</small></b><b v-else>Position unavailable</b></div><div><span>REVIEW STATUS</span><b class="status" :class="active.review?.status ?? 'unreviewed'">{{ active.review?.status ?? 'unreviewed' }}</b></div></div>
    </section>
    <section class="panel position"><div class="panel-head"><div><span class="kicker">02 / POSITION</span><h2>Reported impact</h2></div><span class="axis">x → &nbsp; y ↑</span></div>
     <div class="board"><svg viewBox="0 0 1000 1000" role="img" :aria-label="coordsUsable ? 'Reported board coordinates x ' + coords!.x + ', y ' + coords!.y + ' millimetres' : 'Reported coordinates unavailable'"><circle :cx="C" :cy="C" r="440" class="board-rim"/><path v-for="(cell,i) in cells" :key="i" :d="cell.d" :class="['sector',cell.dark?'dark':'light',cell.segment.ring]"/><circle :cx="C" :cy="C" :r="BULL_OUTER_R" class="bull outer"/><circle :cx="C" :cy="C" :r="BULL_INNER_R" class="bull inner"/><text v-for="n in NUMBERS" :key="n.number" :x="n.x" :y="n.y + 14" class="number">{{ n.number }}</text><template v-for="(dart,i) in occupancy" :key="'o'+i"><circle v-if="dart.coords && xy(dart.coords)" :cx="xy(dart.coords)?.x" :cy="xy(dart.coords)?.y" r="8" class="occupancy-dot"/></template><g v-if="coordsUsable && xy(coords)"><circle :cx="xy(coords)?.x" :cy="xy(coords)?.y" r="27" class="halo"/><circle :cx="xy(coords)?.x" :cy="xy(coords)?.y" r="11" class="pin"/><path :d="'M '+xy(coords)?.x+' '+((xy(coords)?.y ?? 0) - 40)+' v 80 M '+((xy(coords)?.x ?? 0)-40)+' '+xy(coords)?.y+' h 80'" class="cross"/></g><circle v-if="corrected && xy(corrected)" :cx="xy(corrected)?.x" :cy="xy(corrected)?.y" r="20" class="correction"/></svg></div>
     <div class="legend"><span><i class="key-reported"/>Board-reported</span><span v-if="corrected"><i class="key-corrected"/>Manual correction</span></div><p class="schematic">Position uses board-reported millimetres, with the bull as origin. The marker is a comparison reference.</p>
     <label class="field-title">Manual position correction <small>optional · does not change board data</small></label><div class="coordinates"><label>X <input v-model.number="correctedX" type="number" step="0.1" placeholder="mm"/></label><label>Y <input v-model.number="correctedY" type="number" step="0.1" placeholder="mm"/></label><button v-if="corrected" class="clear" @click="corrected = null">Clear</button></div>
    </section>
   </div>
   <section class="panel assessment"><div class="panel-head"><div><span class="kicker">03 / ASSESSMENT</span><h2>Does the reported position look right?</h2></div><span class="shortcut">Keyboard: 1 / 2 / 3</span></div><div class="notes-grid"><label>Reason <small>optional</small><input v-model="reason" placeholder="e.g. impact obscured by shaft"/></label><label>Notes <small>optional</small><textarea v-model="notes" rows="1" placeholder="Context for a later review"/></label></div><div class="decisions"><button class="decision confirm" :disabled="saving" @click="save('confirmed')"><b>✓</b><span><strong>Confirmed</strong><small>Looks correct <kbd>1</kbd></small></span></button><button class="decision incorrect" :disabled="saving" @click="save('incorrect')"><b>×</b><span><strong>Incorrect</strong><small>Position is wrong <kbd>2</kbd></small></span></button><button class="decision uncertain" :disabled="saving" @click="save('uncertain')"><b>?</b><span><strong>Uncertain</strong><small>Needs another look <kbd>3</kbd></small></span></button></div></section>
  </template>
  <Teleport to="body"><div v-if="lightbox" class="lightbox" role="dialog" aria-modal="true" @click.self="lightbox = null"><button class="close" aria-label="Close image" @click="lightbox = null">×</button><img :src="lightbox.url!" :alt="'Original frame from camera ' + lightbox.camera"/><span>Camera {{ lightbox.camera }} · original frame</span></div></Teleport>
 </main>
</template>

<style scoped>
.capture{--panel:#0c202d;--line:#244255;max-width:1680px;margin:0 auto;padding:1.4rem clamp(.7rem,2.2vw,2rem) 3rem;color:var(--ui-text)}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:2rem;padding:1rem 0 1.4rem;border-bottom:1px solid var(--ui-border)}.brand{display:flex;align-items:center;gap:.55rem;margin-bottom:1.5rem;color:#d8e9f2;font-weight:800;font-size:.74rem;letter-spacing:.12em}.brand i{color:var(--ui-muted);font-style:normal;font-weight:500}.brand-mark{display:grid;place-items:center;width:2rem;height:2rem;border:1px solid #56cfff75;border-radius:9px;color:var(--ui-accent);font-size:1.3rem}.eyebrow,.kicker{margin:0;color:var(--ui-accent);font-size:.65rem;font-weight:800;letter-spacing:.15em}.hero h1{margin:.2rem 0;font-size:clamp(2rem,4vw,3rem);letter-spacing:-.055em}.lede{max-width:620px;margin:.45rem 0 0;color:var(--ui-muted);line-height:1.55}.summary{width:min(350px,35%);padding:1rem 1.1rem;border:1px solid var(--line);border-radius:14px;background:linear-gradient(145deg,#123347,#0b1b27);box-shadow:var(--ui-shadow)}.summary-top{display:flex;align-items:baseline;justify-content:space-between}.summary-top b{font-size:1.6rem}.summary-top small{color:var(--ui-muted);font-size:1rem}.summary-top span{color:var(--ui-muted);font-size:.8rem}.progress{height:6px;margin:.65rem 0 .8rem;border-radius:8px;background:#254457;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,#35b7e9,#69d9ad);border-radius:inherit;transition:width .2s}.counts{display:flex;flex-wrap:wrap;gap:.4rem .8rem;color:var(--ui-muted);font-size:.68rem}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:.15rem}.green{background:var(--ui-success)}.red{background:var(--ui-danger)}.amber{background:#ffd37d}.bar{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.85rem 0}.filters{display:flex;gap:.3rem;flex-wrap:wrap}.filters button,.refresh,.navigator button,.navigator select{border:1px solid transparent;border-radius:8px;padding:.5rem .75rem;background:transparent;color:var(--ui-muted);font:inherit;font-size:.78rem;cursor:pointer;text-transform:capitalize}.filters button.active{border-color:#56cfff52;background:#56cfff12;color:var(--ui-accent)}.filters button:hover,.refresh:hover{background:#ffffff0b;color:var(--ui-text)}.refresh{border-color:var(--line);color:var(--ui-secondary);white-space:nowrap}.navigator{display:flex;align-items:center;justify-content:center;gap:.7rem;margin:0 0 .8rem;padding:.55rem;border:1px solid var(--line);border-radius:11px;background:#0a1b27}.navigator button,.navigator select{border-color:var(--line);background:#102636;color:var(--ui-secondary)}.navigator button:disabled{opacity:.35;cursor:default}.position{min-width:125px;text-align:center;color:var(--ui-muted);font-size:.8rem}.position b{color:var(--ui-text)}.navigator select{margin-left:auto;max-width:270px}.columns{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(330px,.85fr);gap:.85rem}.panel{min-width:0;border:1px solid var(--line);border-radius:15px;background:linear-gradient(155deg,#102a3a,#0b1b27);box-shadow:var(--ui-shadow);padding:1rem}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.8rem}.panel h2{margin:.15rem 0 0;font-size:1.08rem;letter-spacing:-.025em}.small-note,.axis,.shortcut{color:var(--ui-muted);font-size:.72rem}.camera-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.65rem}.camera{min-width:0;padding:0;border:1px solid #2a495b;border-radius:10px;background:#07151f;overflow:hidden;color:var(--ui-text);text-align:left;cursor:zoom-in}.camera:disabled{cursor:default}.frame{position:relative;display:grid;place-items:center;aspect-ratio:16/9;background:radial-gradient(ellipse,#19374a,#081722)}.frame img{display:block;width:100%;height:100%;object-fit:contain}.expand{position:absolute;right:.45rem;top:.45rem;display:grid;place-items:center;width:1.6rem;height:1.6rem;border-